// app.js
var WS_URL = "ws://127.0.0.1:8080/ws";
var UPDATE_INTERVAL = 5;
var bridge = null;
function logDebug(msg) {
  console.log(msg);
  const logEl = document.getElementById("debug-log");
  if (logEl) {
    logEl.innerHTML += `
[${(/* @__PURE__ */ new Date()).toISOString().split("T")[1].slice(0, -1)}] ${msg}`;
    logEl.scrollTop = logEl.scrollHeight;
  }
}
function createMetricBitmap(paceStr, hrStr, detailsStr) {
  const canvas = document.createElement("canvas");
  canvas.width = 200;
  canvas.height = 100;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, 200, 100);
  ctx.fillStyle = "#FFFFFF";
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  ctx.font = "bold 24px monospace";
  ctx.fillText(paceStr, 100, 8);
  ctx.fillText(hrStr, 100, 40);
  ctx.font = "bold 15px monospace";
  ctx.fillText(detailsStr, 100, 76);
  const imgData = ctx.getImageData(0, 0, 200, 100).data;
  const rawBytes = new Array(2e4);
  for (let i = 0; i < 2e4; i++) {
    rawBytes[i] = imgData[i * 4];
  }
  return rawBytes;
}
async function updateGlassesDisplay(pace, hr, details) {
  if (!bridge) return;
  const imageBytes = createMetricBitmap(pace, hr, details);
  try {
    await bridge.updateImageRawData({
      containerID: 5,
      containerName: "pace_img",
      imageData: imageBytes
    });
    logDebug(`Pushed display update: ${pace} | ${hr} | ${details}`);
  } catch (err) {
    logDebug(`Update error: ${err.message}`);
  }
}
function connectWebSocket() {
  let socket;
  try {
    socket = new WebSocket(WS_URL);
    logDebug("Connecting WebSocket...");
  } catch (e) {
    return;
  }
  socket.onopen = () => logDebug("WebSocket Connected!");
  socket.onerror = (err) => logDebug("WebSocket Error!");
  let wsMessageCount = 0;
  socket.onmessage = (e) => {
    try {
      logDebug(`Raw WS Payload: ${e.data}`);
      const t22 = JSON.parse(e.data);
      const paceStr = t22.pace ? `${t22.pace} min/km` : "6:30 min/km";
      const hrStr = t22.hr ? `${t22.hr} bpm` : "82 bpm";
      const distStr = t22.distance ? `${t22.distance} km` : "5.72 km";
      const timeStr = t22.timer ? t22.timer : "5:45";
      wsMessageCount++;
      if (wsMessageCount % UPDATE_INTERVAL === 0 || wsMessageCount === 1) {
        updateGlassesDisplay(paceStr, hrStr, `${distStr} | ${timeStr}`);
      }
    } catch (err) {
    }
  };
  socket.onclose = () => {
    logDebug("WebSocket Closed. Reconnecting in 3s...");
    setTimeout(connectWebSocket, 3e3);
  };
}
async function initGlasses() {
  try {
    logDebug("Waiting for Even App Bridge...");
    bridge = await Je();
    logDebug("Bridge connected successfully.");
    const payload = {
      containerTotalNum: 2,
      textObject: [{
        xPosition: 100,
        yPosition: 80,
        width: 240,
        height: 60,
        containerID: 4,
        containerName: "status-text",
        content: "Ready",
        isEventCapture: 1
      }],
      imageObject: [{
        xPosition: 10,
        yPosition: 10,
        width: 200,
        height: 100,
        containerID: 5,
        containerName: "pace_img"
      }]
    };
    logDebug(`
--- INITIALIZING HUD ---`);
    let res = await bridge.createStartUpPageContainer(payload);
    logDebug(`=> Create Code Result: ${res}`);
    if (res === 0) {
      logDebug("HUD Initialized! Pushing layout...");
      await updateGlassesDisplay("6:30 min/km", "82 bpm", "5.72 km | 5:45");
      connectWebSocket();
    } else {
      logDebug("Validation failed. Check payload schema.");
    }
  } catch (e) {
    logDebug("Bridge Init Error: " + (e.stack || e.message));
  }
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initGlasses);
} else {
  initGlasses();
}
